<template><div class="page"><Header/><main><router-link :to="'/profile/orders/'+String(route.params.id||'')">‹ Back to order</router-link><h1>Write a review</h1><p v-if="state==='loading'">Loading order…</p><p v-else-if="state==='error'" class="error">{{error}} <button @click="load">Retry</button></p><template v-else-if="order"><p v-if="order.status!=='DELIVERED'" class="notice">Reviews are only enabled for delivered orders.</p><section v-for="item in reviewableItems" :key="String(item.goodsId)" class="card"><strong>{{item.goodsName||'Product'}}</strong><small>{{item.specText||''}}</small><label>Rating (1–5)<select v-model.number="ratings[String(item.goodsId)]"><option v-for="n in 5" :key="n" :value="n">{{n}}</option></select></label><label>Review (1–500 characters)<textarea v-model="contents[String(item.goodsId)]" minlength="1" maxlength="500"/></label><p v-if="errors[String(item.goodsId)]" class="error">{{errors[String(item.goodsId)]}}</p><button class="primary" @click="submit(item)" :disabled="busyGoodsId===String(item.goodsId)||order.status!=='DELIVERED'">{{busyGoodsId===String(item.goodsId)?'Submitting…':'Submit review'}}</button></section><p v-if="!reviewableItems.length" class="notice">Order detail did not provide a reliable goodsId; reviews cannot be submitted.</p><p v-if="message" :class="failed?'error':'success'">{{message}}</p></template></main><Footer/></div></template>
<script setup lang="ts">
import {computed,onMounted,reactive,ref} from 'vue';import {useRoute} from 'vue-router';import Header from '@/components/Header.vue';import Footer from '@/components/Footer.vue';import {getOrderDetail,saveOrderReview,type OrderItem,type OrderRecord} from '@/api/orders';import {getCustomerAuthState} from '@/utils/customerAuth'
const route=useRoute(),order=ref<OrderRecord|null>(null),state=ref<'loading'|'success'|'error'>('loading'),error=ref(''),message=ref(''),failed=ref(false),busyGoodsId=ref('');const ratings=reactive<Record<string,number>>({}),contents=reactive<Record<string,string>>({}),errors=reactive<Record<string,string>>({});const reviewableItems=computed(()=>order.value?.items?.filter(item=>item.goodsId!==undefined&&item.goodsId!==null)||[])
async function load(){if(!getCustomerAuthState().isAuthenticated){state.value='error';error.value='Please sign in with a customer account.';return}state.value='loading';try{order.value=await getOrderDetail(String(route.params.id||''));state.value='success'}catch(e){state.value='error';error.value=e instanceof Error?e.message:'Unable to load order.'}}
async function submit(item:OrderItem){const id=String(item.goodsId??'');const content=contents[id]?.trim()||'';if(!order.value||!id||busyGoodsId.value)return;if(order.value.status!=='DELIVERED'){errors[id]='Only delivered orders can be reviewed.';return}if(content.length<1||content.length>500){errors[id]='Review must contain 1–500 characters.';return}errors[id]='';busyGoodsId.value=id;message.value='';failed.value=false;try{await saveOrderReview(String(order.value.orderId),{goodsId:item.goodsId!,rating:Math.min(5,Math.max(1,Number(ratings[id]||5))),content});message.value='Review submitted.';contents[id]=''}catch(e){failed.value=true;message.value=e instanceof Error?e.message:'Unable to submit review.'}finally{busyGoodsId.value=''}}
onMounted(load)
</script>
<style scoped>.page{min-height:100vh;background:#f4f4f5;color:#333;font:13px Arial}.page main{max-width:850px;margin:24px auto;padding:0 16px}.page h1{font-size:18px}.card{background:white;border:1px solid #e2e5e8;border-radius:6px;padding:16px;margin:12px 0;display:flex;flex-direction:column;gap:9px}.card small{color:#666}.card label{display:flex;flex-direction:column;gap:6px}.card textarea,.card select{min-height:36px;border:1px solid #d1d5db;border-radius:4px;padding:8px;font:13px Arial}.card textarea{height:100px}.primary{height:36px;padding:0 15px;color:#fff;background:#333;border:0;border-radius:4px;align-self:flex-start}.primary:disabled{opacity:.55}.error{color:#a63805}.success{color:#18794e}.notice{padding:12px;background:#fff4e5;border-radius:4px}@media(max-width:650px){.page main{margin:12px auto}.card{padding:12px}}</style>

